CREATE TABLE IF NOT EXISTS schema_version(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE users(id TEXT PRIMARY KEY, username TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('Admin','Analyst','Viewer')), enabled INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), csrf TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE TABLE login_attempts(identity TEXT PRIMARY KEY, failures INTEGER NOT NULL, until_time TEXT NOT NULL);
CREATE TABLE settings(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE collectors(id TEXT PRIMARY KEY, name TEXT NOT NULL, kind TEXT NOT NULL, token_hash TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, device_id TEXT, expected_host TEXT, created_at TEXT NOT NULL, last_seen TEXT, last_ingest TEXT, last_event TEXT, accepted INTEGER NOT NULL DEFAULT 0, rejected INTEGER NOT NULL DEFAULT 0, parse_failures INTEGER NOT NULL DEFAULT 0, diagnostics TEXT NOT NULL DEFAULT '{}');
CREATE TABLE checkpoints(collector_id TEXT NOT NULL REFERENCES collectors(id), source TEXT NOT NULL, bookmark TEXT, updated_at TEXT NOT NULL, PRIMARY KEY(collector_id,source));
CREATE TABLE devices(id TEXT PRIMARY KEY, hostname TEXT UNIQUE NOT NULL, sid TEXT, os TEXT, ips TEXT NOT NULL DEFAULT '[]', agent_version TEXT, last_heartbeat TEXT, last_event TEXT, errors TEXT NOT NULL DEFAULT '[]', inventory_at TEXT);
CREATE TABLE employees(sid TEXT PRIMARY KEY, account TEXT NOT NULL, name TEXT, department TEXT, enabled INTEGER NOT NULL DEFAULT 1, synced_at TEXT NOT NULL);
CREATE TABLE directory_groups(sid TEXT PRIMARY KEY, name TEXT NOT NULL, synced_at TEXT NOT NULL);
CREATE TABLE memberships(employee_sid TEXT NOT NULL REFERENCES employees(sid), group_sid TEXT NOT NULL REFERENCES directory_groups(sid), PRIMARY KEY(employee_sid,group_sid));
CREATE TABLE associations(employee_sid TEXT NOT NULL, device_id TEXT NOT NULL REFERENCES devices(id), confidence TEXT NOT NULL, reason TEXT NOT NULL, first_seen TEXT NOT NULL, last_seen TEXT NOT NULL, is_primary INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(employee_sid,device_id));
CREATE TABLE inbox(id INTEGER PRIMARY KEY AUTOINCREMENT, collector_id TEXT NOT NULL REFERENCES collectors(id), transport_id TEXT NOT NULL, payload TEXT NOT NULL, received_at TEXT NOT NULL, processed INTEGER NOT NULL DEFAULT 0, error TEXT, UNIQUE(collector_id,transport_id));
CREATE INDEX ix_inbox_work ON inbox(processed,id);
CREATE TABLE events(id TEXT PRIMARY KEY, identity TEXT UNIQUE NOT NULL, time TEXT NOT NULL, received_at TEXT NOT NULL, event_id INTEGER, provider TEXT, channel TEXT, source_computer TEXT NOT NULL, collector_id TEXT NOT NULL REFERENCES collectors(id), source_record TEXT, user_sid TEXT, account TEXT, logon_id TEXT, device_id TEXT REFERENCES devices(id), access_device_id TEXT REFERENCES devices(id), attribution TEXT NOT NULL, category TEXT NOT NULL, result TEXT NOT NULL, object_path TEXT, canonical_path TEXT, source_address TEXT, process_id TEXT, process_guid TEXT, parent_id TEXT, process_path TEXT, command_line TEXT, fields TEXT NOT NULL, raw TEXT, evidence_type TEXT NOT NULL, late_seconds REAL NOT NULL, rules_done INTEGER NOT NULL DEFAULT 0);
CREATE INDEX ix_events_time ON events(time);
CREATE INDEX ix_events_user ON events(user_sid,time);
CREATE INDEX ix_events_device ON events(device_id,time);
CREATE INDEX ix_events_access_device ON events(access_device_id,time);
CREATE INDEX ix_events_type ON events(event_id,provider,channel,time);
CREATE INDEX ix_events_logon ON events(source_computer,logon_id,time);
CREATE TABLE health(id TEXT PRIMARY KEY, device_id TEXT NOT NULL REFERENCES devices(id), sampled_at TEXT NOT NULL, received_at TEXT NOT NULL, cpu REAL, ram_percent REAL, ram_used INTEGER, ram_available INTEGER, ram_total INTEGER, disks TEXT NOT NULL);
CREATE INDEX ix_health_device ON health(device_id,received_at);
CREATE TABLE heartbeats(id TEXT PRIMARY KEY, device_id TEXT NOT NULL REFERENCES devices(id), sampled_at TEXT NOT NULL, received_at TEXT NOT NULL, sessions TEXT NOT NULL, errors TEXT NOT NULL);
CREATE INDEX ix_heartbeats_device ON heartbeats(device_id,received_at);
CREATE TABLE endpoint_sessions(id TEXT PRIMARY KEY, device_id TEXT NOT NULL REFERENCES devices(id), session_key TEXT NOT NULL, account TEXT, state TEXT, observed_at TEXT NOT NULL);
CREATE TABLE usb(id TEXT PRIMARY KEY, device_id TEXT NOT NULL REFERENCES devices(id), time TEXT NOT NULL, received_at TEXT NOT NULL, action TEXT NOT NULL, identifier TEXT NOT NULL, account TEXT, metadata TEXT NOT NULL, evidence_type TEXT NOT NULL);
CREATE INDEX ix_usb_device ON usb(device_id,time);
CREATE TABLE rules(id TEXT PRIMARY KEY, name TEXT NOT NULL, enabled INTEGER NOT NULL, version INTEGER NOT NULL, config TEXT NOT NULL, required TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE rule_versions(rule_id TEXT NOT NULL, version INTEGER NOT NULL, config TEXT NOT NULL, enabled INTEGER NOT NULL, actor TEXT NOT NULL, time TEXT NOT NULL, PRIMARY KEY(rule_id,version));
CREATE TABLE alerts(id TEXT PRIMARY KEY, fingerprint TEXT UNIQUE NOT NULL, kind TEXT NOT NULL, rule_id TEXT, rule_version INTEGER, title TEXT NOT NULL, severity TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Open', disposition TEXT, assigned_to TEXT REFERENCES users(id), user_sid TEXT, account TEXT, device_id TEXT REFERENCES devices(id), first_time TEXT NOT NULL, last_time TEXT NOT NULL, created_at TEXT NOT NULL, explanation TEXT NOT NULL, config_snapshot TEXT NOT NULL);
CREATE INDEX ix_alerts_filter ON alerts(status,severity,last_time);
CREATE TABLE alert_evidence(alert_id TEXT NOT NULL REFERENCES alerts(id) ON DELETE CASCADE, event_id TEXT NOT NULL REFERENCES events(id), PRIMARY KEY(alert_id,event_id));
CREATE TABLE case_history(id TEXT PRIMARY KEY, alert_id TEXT NOT NULL REFERENCES alerts(id) ON DELETE CASCADE, actor TEXT NOT NULL, time TEXT NOT NULL, action TEXT NOT NULL, body TEXT NOT NULL);
CREATE TABLE features(id TEXT PRIMARY KEY, user_sid TEXT NOT NULL, start_time TEXT NOT NULL, end_time TEXT NOT NULL, schema_version INTEGER NOT NULL, values_json TEXT NOT NULL, evidence_ids TEXT NOT NULL, provenance TEXT NOT NULL, UNIQUE(user_sid,start_time,schema_version));
CREATE TABLE models(id TEXT PRIMARY KEY, created_at TEXT NOT NULL, active INTEGER NOT NULL, metadata TEXT NOT NULL, path TEXT NOT NULL, sha256 TEXT NOT NULL);
CREATE TABLE model_scores(model_id TEXT NOT NULL REFERENCES models(id), feature_id TEXT NOT NULL REFERENCES features(id), score REAL NOT NULL, baseline_kind TEXT NOT NULL, explanation TEXT NOT NULL, PRIMARY KEY(model_id,feature_id));
CREATE TABLE audit(id TEXT PRIMARY KEY, time TEXT NOT NULL, actor TEXT NOT NULL, action TEXT NOT NULL, details TEXT NOT NULL);
